import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { AdminService } from '../../core/admin.service';

interface FieldDef { key: string; label: string; type?: 'text' | 'number' | 'datetime-local' | 'select' | 'checkbox'; options?: string[]; }
interface ResourceDef {
  key: string;           // API path segment
  title: string;
  columns: string[];     // fields shown in table
  fields: FieldDef[];    // fields shown in the add/edit form
}

const RESOURCES: ResourceDef[] = [
  {
    key: 'users', title: 'Users',
    columns: ['id', 'name', 'email', 'phone', 'role'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'email', label: 'Email' },
      { key: 'phone', label: 'Phone' },
      { key: 'role', label: 'Role', type: 'select', options: ['member', 'admin'] },
    ],
  },
  {
    key: 'trainers', title: 'Trainers',
    columns: ['id', 'name', 'specialty'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'specialty', label: 'Specialty' },
      { key: 'bio', label: 'Bio' },
    ],
  },
  {
    key: 'classes', title: 'Classes',
    columns: ['id', 'name', 'trainer_name', 'location', 'starts_at', 'capacity', 'spots_left'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'trainer_id', label: 'Trainer ID', type: 'number' },
      { key: 'category', label: 'Category' },
      { key: 'location', label: 'Location' },
      { key: 'starts_at', label: 'Starts At', type: 'datetime-local' },
      { key: 'ends_at', label: 'Ends At', type: 'datetime-local' },
      { key: 'capacity', label: 'Capacity', type: 'number' },
    ],
  },
  {
    key: 'plans', title: 'Membership Plans',
    columns: ['id', 'name', 'price', 'classes_per_month', 'duration_months', 'is_active'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'price', label: 'Price', type: 'number' },
      { key: 'classes_per_month', label: 'Classes/Month (blank=unlimited)', type: 'number' },
      { key: 'duration_months', label: 'Duration (months)', type: 'number' },
      { key: 'is_active', label: 'Active', type: 'checkbox' },
    ],
  },
  {
    key: 'memberships', title: 'Memberships',
    columns: ['id', 'user_name', 'plan_name', 'status', 'classes_used_this_month', 'renews_at'],
    fields: [
      { key: 'status', label: 'Status', type: 'select', options: ['active', 'expired', 'cancelled'] },
      { key: 'plan_id', label: 'Plan ID', type: 'number' },
      { key: 'renews_at', label: 'Renews At', type: 'datetime-local' },
    ],
  },
  {
    key: 'bookings', title: 'Bookings',
    columns: ['id', 'user_name', 'class_name', 'starts_at', 'status'],
    fields: [
      { key: 'status', label: 'Status', type: 'select', options: ['booked', 'cancelled', 'attended', 'no_show'] },
    ],
  },
];

@Component({
  selector: 'app-admin',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './admin.component.html',
  styleUrl: './admin.component.css',
})
export class AdminComponent implements OnInit {
  resources = RESOURCES;
  active: ResourceDef = RESOURCES[0];
  rows: any[] = [];
  loading = false;
  error = '';

  showForm = false;
  editingId: number | null = null;
  formModel: any = {};

  stats: any = null;

  constructor(private admin: AdminService) {}

  async ngOnInit() {
    this.stats = await this.admin.stats().catch(() => null);
    await this.select(this.resources[0]);
  }

  async select(res: ResourceDef) {
    this.active = res;
    this.showForm = false;
    this.error = '';
    this.loading = true;
    try {
      this.rows = await this.admin.list(res.key);
    } catch (e: any) {
      this.error = e?.error?.error || 'Failed to load data';
      this.rows = [];
    } finally {
      this.loading = false;
    }
  }

  openCreate() {
    this.editingId = null;
    this.formModel = {};
    this.showForm = true;
  }

  openEdit(row: any) {
    this.editingId = row.id;
    this.formModel = { ...row };
    this.showForm = true;
  }

  cancelForm() {
    this.showForm = false;
    this.editingId = null;
  }

  async save() {
    try {
      if (this.editingId) {
        await this.admin.update(this.active.key, this.editingId, this.formModel);
      } else {
        await this.admin.create(this.active.key, this.formModel);
      }
      this.showForm = false;
      await this.select(this.active);
    } catch (e: any) {
      this.error = e?.error?.error || 'Save failed';
    }
  }

  async remove(row: any) {
    if (!confirm(`Delete this ${this.active.title.slice(0, -1)}?`)) return;
    try {
      await this.admin.remove(this.active.key, row.id);
      await this.select(this.active);
    } catch (e: any) {
      this.error = e?.error?.error || 'Delete failed';
    }
  }
}
<div class="admin-shell">
  <aside class="admin-nav">
    <h2>Admin</h2>
    <a routerLink="/app" class="back-link">← Back to app</a>
    <nav>
      <button *ngFor="let r of resources"
              [class.active]="r.key === active.key"
              (click)="select(r)">{{ r.title }}</button>
    </nav>
    <div class="stats" *ngIf="stats">
      <div>Users: {{ stats.users }}</div>
      <div>Trainers: {{ stats.trainers }}</div>
      <div>Upcoming classes: {{ stats.upcoming_classes }}</div>
      <div>Active memberships: {{ stats.active_memberships }}</div>
      <div>Bookings today: {{ stats.bookings_today }}</div>
    </div>
  </aside>

  <main class="admin-main">
    <div class="admin-header">
      <h1>{{ active.title }}</h1>
      <button class="btn-primary" (click)="openCreate()">+ Add</button>
    </div>

    <p class="error" *ngIf="error">{{ error }}</p>
    <p *ngIf="loading">Loading…</p>

    <table *ngIf="!loading && rows.length">
      <thead>
        <tr>
          <th *ngFor="let c of active.columns">{{ c }}</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let row of rows">
          <td *ngFor="let c of active.columns">{{ row[c] }}</td>
          <td class="row-actions">
            <button (click)="openEdit(row)">Edit</button>
            <button class="btn-danger" (click)="remove(row)">Delete</button>
          </td>
        </tr>
      </tbody>
    </table>

    <p *ngIf="!loading && !rows.length">No records.</p>
  </main>

  <div class="modal-backdrop" *ngIf="showForm" (click)="cancelForm()">
    <div class="modal" (click)="$event.stopPropagation()">
      <h3>{{ editingId ? 'Edit' : 'Add' }} {{ active.title.slice(0, -1) }}</h3>
      <form (ngSubmit)="save()">
        <label *ngFor="let f of active.fields">
          {{ f.label }}
          <select *ngIf="f.type === 'select'" [(ngModel)]="formModel[f.key]" [name]="f.key">
            <option *ngFor="let o of f.options" [value]="o">{{ o }}</option>
          </select>
          <input *ngIf="f.type === 'checkbox'" type="checkbox" [(ngModel)]="formModel[f.key]" [name]="f.key" />
          <input *ngIf="!f.type || (f.type !== 'select' && f.type !== 'checkbox')"
                 [type]="f.type || 'text'" [(ngModel)]="formModel[f.key]" [name]="f.key" />
        </label>
        <div class="modal-actions">
          <button type="button" (click)="cancelForm()">Cancel</button>
          <button type="submit" class="btn-primary">Save</button>
        </div>
      </form>
    </div>
  </div>
</div>
